/** Independent EVAL adapter identity over 076. Original records are facts, never a send grant. */
public final class FormalEvaluationInvocationRecords {
 private final JdbcTemplate db;private final FormalInvocationSchema schema;private final FormalEvaluationInvocationObjects objects;
 public FormalEvaluationInvocationRecords(DataSource data,FormalInvocationSchema schema,FormalEvaluationInvocationObjects objects){this.objects=objects;db=new JdbcTemplate(data);db.setQueryTimeout(5);this.schema=schema;}
 Binding register(FormalEvaluationInvocationService.PreparedContent prepared,FormalEvaluationInvocationObjects.Registered exact,JsonNode request,JsonNode dependencies)throws Exception {
  prepared.requireUnchanged();exact.requireUnchanged();var session=prepared.session();if(!Arrays.equals(prepared.bytes(),exact.bytes())||!prepared.provenance().equals(exact.receipt().required("provenance")))bad();
  session.requireCurrent();var lease=session.lease();var j=lease.job();var input=lease.input();input.requireCurrent(lease.admission());
  String context=UUID.nameUUIDFromBytes(("EVALUATION_C07/"+j.runId()+"/"+lease.stepId()+"/"+session.sessionId()+"/"+prepared.requestId()+"/"+prepared.ordinal()).getBytes(StandardCharsets.US_ASCII)).toString();
  String action=UUID.nameUUIDFromBytes(("EVALUATION_MODEL_CALL/"+context).getBytes(StandardCharsets.US_ASCII)).toString();
  var deps=(ObjectNode)dependencies.deepCopy();deps.put("tenant_id",j.tenantId()).put("project_id",j.projectId()).put("actor_id",j.actorId()).put("run_id",j.runId()).put("principal_id",j.principalId()).put("step_id",lease.stepId()).put("session_id",session.sessionId()).put("lease_generation",Long.toString(lease.generation())).put("worker_service_uri",lease.workerService()).put("input_sha256",input.sha256()).put("classification",j.classification()).put("admission_sha256",j.admissionSha256());
  deps.set("host_binding",session.binding());deps.set("input_evidence",input.evidence());deps.put("exact_input_artifact_id",exact.artifactId()).put("exact_input_receipt_sha256",schema.hash(exact.receipt()));deps.set("exact_input_receipt",exact.receipt());deps.put("request_id",prepared.requestId()).put("ordinal",Long.toString(prepared.ordinal()));
  String raw=schema.canonical(request),hash=schema.hash(request),dependency=schema.canonical(deps),dependencyHash=schema.hash(deps);
  String access=exact.accessSetId();
  var doc=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("execution_kind","SYSTEM_JOB").put("job_type","EVALUATION_VERIFICATION").put("node_kind",lease.node().node().nodeKind());doc.set("request",request);doc.set("dependencies",deps);
  String source=schema.canonical(doc),digest=schema.hash(doc);
  if(db.queryForList("SELECT context_manifest_id FROM formal_evaluation_invocation_context WHERE tenant_id=? AND context_manifest_id=? FOR UPDATE",j.tenantId(),context).isEmpty()){
   var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));
   changed(db.update("INSERT INTO version_registry(tenant_id,version_id,owner_project_id,entity_kind,content_sha256) VALUES(?,?,?,'CONTEXT_MANIFEST',?)",j.tenantId(),context,j.projectId(),digest));
   changed(db.update("INSERT INTO context_manifest(tenant_id,project_id,context_manifest_id,exact_input_ref,source_manifest,prompt_revision,tokenizer_revision,token_count,dependency_access_set_id,content_sha256,execution_mode,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,?,?,?,?,'EXTERNAL','1.0.0',?,?,?,?)",j.tenantId(),j.projectId(),context,schema.canonical(request.required("exact_input")),source,text(request.required("prompt_basis"),"version_id"),text(request.required("tokenizer_basis"),"version_id"),text(request,"maximum_input_tokens"),access,digest,schema.manifestSha256(),j.actorId(),now,j.classification()));

   changed(db.update("INSERT INTO step_action_binding(tenant_id,project_id,run_id,step_id,action_id,input_sha256,origin_run_id,origin_step_id,origin_action_id,kind,arguments_sha256,tool_version,state,lease_generation,schema_version,schema_manifest_sha256,created_by,created_at,classification,revision,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'MODEL_CALL',?,?,'BOUND',?,'1.0.0',?,?,?,?,1,?)",j.tenantId(),j.projectId(),j.runId(),lease.stepId(),action,input.sha256(),j.runId(),lease.stepId(),action,hash,text(request,"model_config_revision"),lease.generation(),schema.manifestSha256(),j.actorId(),now,j.classification(),now));
   changed(db.update("INSERT INTO formal_evaluation_invocation_context(tenant_id,project_id,run_id,step_id,session_id,request_id,ordinal,context_manifest_id,action_id,lease_generation,canonical_request,request_sha256,canonical_dependencies,dependencies_sha256,source_sha256,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'1.0.0',?,?,?,?)",j.tenantId(),j.projectId(),j.runId(),lease.stepId(),session.sessionId(),prepared.requestId(),prepared.ordinal(),context,action,lease.generation(),raw,hash,dependency,dependencyHash,digest,schema.manifestSha256(),j.actorId(),now,j.classification()));
   changed(db.update("INSERT INTO audit_event(tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,'evaluation.context.registered',?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",j.tenantId(),j.projectId(),context,j.actorId(),source,context,j.runId(),schema.manifestSha256(),j.actorId(),now,j.classification()));
   changed(db.update("INSERT INTO outbox_event(tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES(?,?,?,1,'evaluation.context.registered',?,?)",j.tenantId(),context,context,source,now));

  }
  var result=read(j.tenantId(),context);if(!result.request().equals(raw)||!result.dependencies().equals(dependency))bad();session.requireCurrent();return result;
 }
 Binding read(String tenant,String context)throws Exception {
  current(tenant);var row=one(db.queryForList("SELECT * FROM formal_evaluation_invocation_context WHERE tenant_id=? AND context_manifest_id=? LIMIT 2",tenant,context));
  var request=schema.parse(str(row,"canonical_request"));var deps=schema.parse(str(row,"canonical_dependencies"));same(schema.hash(request),str(row,"request_sha256"));same(schema.hash(deps),str(row,"dependencies_sha256"));same(schema.manifestSha256(),str(row,"schema_manifest_sha256"));same("1.0.0",str(row,"schema_version"));
  for(String key:List.of("tenant_id","project_id","run_id","step_id","session_id","request_id","ordinal","lease_generation"))same(str(row,key),text(deps,key));same(str(row,"created_by"),text(deps,"actor_id"));same(str(row,"classification"),text(deps,"classification"));
  if(!"SYSTEM_JOB".equals(text(request,"execution_kind"))||!"EVALUATION_VERIFICATION".equals(text(request,"job_type")))bad();
  var source=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("execution_kind","SYSTEM_JOB").put("job_type","EVALUATION_VERIFICATION").put("node_kind",text(request,"node_kind"));source.set("request",request);source.set("dependencies",deps);same(schema.hash(source),str(row,"source_sha256"));
  var c=one(db.queryForList("SELECT * FROM context_manifest WHERE tenant_id=? AND context_manifest_id=? LIMIT 2",tenant,context));same(schema.canonical(source),str(c,"source_manifest"));same(schema.hash(source),str(c,"content_sha256"));same(schema.canonical(request.required("exact_input")),str(c,"exact_input_ref"));same(schema.manifestSha256(),str(c,"schema_manifest_sha256"));same(str(row,"created_by"),str(c,"created_by"));same(str(row,"project_id"),str(c,"project_id"));
  same(schema.hash(source),one(db.query("SELECT content_sha256 FROM version_registry WHERE tenant_id=? AND version_id=? AND owner_project_id=? AND entity_kind='CONTEXT_MANIFEST' LIMIT 2",(r,n)->r.getString(1),tenant,context,str(row,"project_id"))));
  var exact=request.required("exact_input");var physical=objects.requireStored(tenant,text(exact,"artifact_id"));same(schema.hash(physical.receipt()),text(deps,"exact_input_receipt_sha256"));same(physical.receipt(),deps.required("exact_input_receipt"));byte[] bytes=physical.bytes();same(WireValues.sha256(bytes),text(exact,"sha256"));

  var artifact=one(db.queryForList("SELECT sha256,dependency_access_set_id FROM artifact WHERE tenant_id=? AND project_id=? AND artifact_id=? LIMIT 2",tenant,str(row,"project_id"),text(exact,"artifact_id")));same(text(exact,"sha256"),str(artifact,"sha256"));same(str(c,"dependency_access_set_id"),str(artifact,"dependency_access_set_id"));
  same(text(deps,"admission_sha256"),one(db.query("SELECT e.admission_sha256 FROM formal_evaluation_job e JOIN system_job_run j ON j.tenant_id=e.tenant_id AND j.run_id=e.run_id WHERE e.tenant_id=? AND e.run_id=? AND e.project_id=? AND e.created_by=? AND j.execution_kind='SYSTEM_JOB' AND j.job_type='EVALUATION_VERIFICATION' LIMIT 2",(r,n)->r.getString(1),tenant,text(deps,"run_id"),text(deps,"project_id"),text(deps,"actor_id"))));
  same(schema.canonical(source),one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND subject_id=? AND created_by=? AND action='evaluation.context.registered' AND result='SUCCESS' AND request_id=? AND trace_id=? AND schema_manifest_sha256=? LIMIT 2",(r,n)->r.getString(1),tenant,text(deps,"project_id"),text(deps,"actor_id"),text(deps,"actor_id"),context,text(deps,"run_id"),schema.manifestSha256())));
  same(schema.canonical(source),one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type='evaluation.context.registered' LIMIT 2",(r,n)->r.getString(1),tenant,context,context)));
  var session=one(db.queryForList("SELECT canonical_start,start_sha256 FROM professional_runtime_session WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND session_id=? AND lease_generation=? AND created_by=? LIMIT 2",tenant,text(deps,"project_id"),text(deps,"run_id"),text(deps,"step_id"),text(deps,"session_id"),text(deps,"lease_generation"),text(deps,"actor_id")));var sessionStart=schema.parse(str(session,"canonical_start"));same(schema.hash(sessionStart),str(session,"start_sha256"));same("EVALUATION_VERIFICATION",text(sessionStart,"purpose"));same(deps.required("host_binding"),sessionStart.required("binding"));
  return new Binding(context,str(row,"action_id"),schema.canonical(request),schema.hash(request),schema.canonical(deps),schema.hash(deps),request,deps);
 }
 static final class Binding implements FormalInvocationBinding {
  private final String context,action,request,requestHash,dependencies,dependenciesHash;private final JsonNode r,d;
  private Binding(String c,String a,String r,String rh,String d,String dh,JsonNode request,JsonNode deps){context=c;action=a;this.request=r;requestHash=rh;dependencies=d;dependenciesHash=dh;this.r=request.deepCopy();this.d=deps.deepCopy();}
  public String tenant(){return text(d,"tenant_id");}public String project(){return text(d,"project_id");}public String actor(){return text(d,"actor_id");}public String run(){return text(d,"run_id");}public String principal(){return text(d,"principal_id");}public String step(){return text(d,"step_id");}public String action(){return action;}public String context(){return context;}public String model(){return text(r,"model_config_revision");}public String verification(){return text(d.required("model_eligibility"),"connection_verification_id");}public String request(){return request;}public String requestHash(){return requestHash;}public String inputHash(){return text(d,"input_sha256");}public String dependencies(){return dependencies;}public String dependenciesHash(){return dependenciesHash;}public String classification(){return text(d,"classification");}String generation(){return text(d,"lease_generation");}String session(){return text(d,"session_id");}JsonNode evidence(){return d.deepCopy();}
  JsonNode snapshot(){return new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("execution_kind","SYSTEM_JOB").put("job_type","EVALUATION_VERIFICATION").put("node_kind",text(r,"node_kind")).put("context_manifest_id",context).put("action_id",action);}
 }
 boolean supports(String tenant,String invocation){return !db.queryForList("SELECT i.invocation_id FROM invocation i JOIN formal_evaluation_invocation_context c ON c.tenant_id=i.tenant_id AND c.context_manifest_id=i.context_manifest_id WHERE i.tenant_id=? AND i.invocation_id=?",tenant,invocation).isEmpty();}
 Binding byInvocation(String tenant,String invocation)throws Exception {
  current(tenant);var row=one(db.queryForList("SELECT i.*,b.canonical_request,b.authorization_snapshot,b.authorization_sha256 FROM invocation i JOIN formal_invocation_binding b ON b.tenant_id=i.tenant_id AND b.invocation_id=i.invocation_id WHERE i.tenant_id=? AND i.invocation_id=? LIMIT 2",tenant,invocation));var b=read(tenant,str(row,"context_manifest_id"));var auth=schema.parse(str(row,"authorization_snapshot"));same(schema.hash(auth),str(row,"authorization_sha256"));same(b.snapshot(),auth.required("evaluation_binding"));same(b.request(),str(row,"canonical_request"));same(b.dependenciesHash(),text(auth,"job_dependency_sha256"));same(b.generation(),text(auth,"lease_generation"));
  for(var e:Map.of("run_id",b.run(),"step_id",b.step(),"action_id",b.action(),"project_id",b.project(),"created_by",b.actor(),"input_sha256",b.inputHash(),"config_revision",b.model(),"lease_generation",b.generation(),"verification_id",b.verification()).entrySet())same(e.getValue(),str(row,e.getKey()));return b;
 }
 List<ArtifactRegistryProtocol.MemberRow> contentMembers(Binding b)throws Exception {read(b.tenant(),b.context());return db.query("SELECT m.upstream_version_id,m.rights_revision FROM dependency_access_member m JOIN artifact a ON a.tenant_id=m.tenant_id AND a.dependency_access_set_id=m.access_set_id WHERE a.tenant_id=? AND a.artifact_id=? ORDER BY m.upstream_version_id",(r,n)->new ArtifactRegistryProtocol.MemberRow(r.getString(1),r.getString(2)),b.tenant(),text(schema.parse(b.request()).required("exact_input"),"artifact_id"));}
 void requireOutput(Binding b,String kind,byte[] bytes)throws Exception {read(b.tenant(),b.context());if(!Set.of("MODEL_RESULT","PROVIDER_CAPTURE").contains(kind)||bytes.length<1||bytes.length>16777216)bad();if("MODEL_RESULT".equals(kind)){var v=schema.parse(new String(bytes,StandardCharsets.UTF_8));same(b.context(),text(v,"context_manifest_id"));same(b.model(),text(v,"model_config_revision"));}}
 void requireProduction(Binding b,FormalInvocationOutcomeAuthority.VerifiedOutcome p,String kind,byte[] bytes)throws Exception {p.requireActive();requireOutput(b,kind,bytes);same(b.actor(),p.actorId());same(b.run(),text(p.binding(),"run_id"));same(b.action(),text(p.binding(),"action_id"));var auth=schema.parse(one(db.query("SELECT authorization_snapshot FROM formal_invocation_binding WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->r.getString(1),b.tenant(),p.invocationId())));var commitment=auth.required("evaluation_output_commitment");same(p.invocationId(),text(commitment,"invocation_id"));same(b.context(),text(commitment,"context_manifest_id"));same(b.evidence().required("output_storage"),commitment.required("storage"));same(b.evidence().required("output_retention"),commitment.required("output_retention"));if(bytes.length>commitment.required("maximum_bytes").intValue())bad();var created=one(db.query("SELECT created_at FROM system_job_run WHERE tenant_id=? AND run_id=? LIMIT 2",(r,n)->r.getTimestamp(1).toInstant(),b.tenant(),b.run()));TaskInvocationOutputPolicy.requireOriginal(commitment.required("output_retention"),b.run(),created,b.evidence().required("retention"));}
 void requireRecoveryPolicy(Binding b,FormalInvocationOutcomeAuthority.VerifiedOutcome p,RuntimeObjectTransport transport)throws Exception {requireProduction(b,p,"MODEL_RESULT",p.bytes());same(schema.parse(schema.canonical(transport.storageBinding())),b.evidence().required("output_storage"));}
 static String text(JsonNode n,String k){if(!n.required(k).isTextual())bad();return n.required(k).textValue();}private static String str(Map<String,Object> r,String k){if(r.get(k)==null)bad();return r.get(k).toString();}private static void current(String t){if(!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()||!TenantScope.requireCurrent().tenantId().equals(t))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static <T>T one(List<T> rows){if(rows.size()!=1)bad();return rows.get(0);}private static void changed(int n){if(n!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
